/* @lc app=leetcode id=1976 lang=kotlin */ class Solution { fun countPaths(n: Int, roads: Array<IntArray>): Int = roads.flatMap { (a, b, w) -> listOf(a to (b to w.toLong()), b to (a to w.toLong())) }.groupBy({ it.first }, { it.second }).let { g -> LongArray(n) { Long.MAX_VALUE }.also { it[0] = 0 }.let { d -> LongArray(n).also { it[0] = 1 }.let { ways -> java.util.PriorityQueue<Pair<Long, Int>>(compareBy<Pair<Long, Int>> { it.first }).also { it.add(0L to 0) }.let { pq -> generateSequence { pq.poll() }.filter { (c, u) -> c == d[u] }.forEach { (c, u) -> g[u].orEmpty().forEach { (v, w) -> if (c + w < d[v]) pq.add(c + w to v).also { d[v] = c + w }.also { ways[v] = ways[u] } else if (c + w == d[v]) ways[v] = (ways[v] + ways[u]) % 1_000_000_007 } }.let { ways[n - 1].toInt() } } } } } }